 */
#[Hook('filter_format_presave')]
public function filterFormatPresave(FilterFormatInterface $format): void {
  // The text format being created cannot have a text editor yet.
  if ($format->isNew()) {
    return;
  }
  /** @var \Drupal\filter\FilterFormatInterface $original */
  $original = \Drupal::entityTypeManager()->getStorage('filter_format')->loadUnchanged($format->getOriginalId());
  // If the text format status is the same, return early.
  if (($status = $format->status()) === $original->status()) {
    return;
  }
  /** @var \Drupal\editor\EditorInterface $editor */
  if ($editor = Editor::load($format->id())) {
    $editor->setStatus($status)->save();
  }
}

/**
 * Records file usage of files referenced by formatted text fields.
 *
 * Each referenced file that is temporally saved will be resaved as permanent.
 *
 * @param array $uuids
 *   An array of file entity UUIDs.
 * @param \Drupal\Core\Entity\EntityInterface $entity
 *   An entity whose fields to inspect for file references.
 */
protected function recordFileUsage(array $uuids, EntityInterface $entity): void {
  if (!\Drupal::getContainer()->has('file.usage')) {
    return;
  }

  $entity_repository = \Drupal::service('entity.repository');
  $file_usage = \Drupal::service('file.usage');

  foreach ($uuids as $uuid) {
    if ($file = $entity_repository->loadEntityByUuid('file', $uuid)) {
      assert($file instanceof FileInterface);
      if ($file->isTemporary()) {
        $file->setPermanent();
        $file->save();
      }
      $file_usage->add($file, 'editor', $entity->getEntityTypeId(), $entity->id());
    }
  }
}

