   * @return string
   *   The bundle or empty string.
   */
  protected function extractBundle(array $data): string {
    // Direct bundle field.
    if (!empty($data['bundle'])) {
      return $data['bundle'];
    }

    // Direct bundle_id field (for create_bundle operations).
    if (!empty($data['bundle_id'])) {
      return $data['bundle_id'];
