public function extensionToImageType($extension) {
  if (in_array($extension, ['jpe', 'jpg'])) {
    $extension = 'jpeg';
  }
  foreach ($this->supportedTypes() as $type) {
    if (image_type_to_extension($type, FALSE) === $extension) {
      return $type;
    }
  }
  return IMAGETYPE_UNKNOWN;
}

