    $this->derivatives['createForEachIfNotExists'] = $base_plugin_definition + [
      'create_action' => 'createIfNotExists',
    ];
    $this->derivatives['createForEach'] = $base_plugin_definition + [
      'create_action' => 'create',
    ];
    return $this->derivatives;
  }

}

