/**
 * Tests the self-healing of the redirect with conditional cache contexts.
 *
 * @todo Revisit now that we have self-healing tests for VariationCache. This
 * is essentially a clone of the other bubbling tests now.
 */
public function testConditionalCacheContextBubblingSelfHealing(): void {
  $current_user_role = &$this->currentUserRole;

  $this->setUpRequest();
  $this->setUpMemoryCache();

  $test_element = [
    '#cache' => [
      'keys' => ['parent'],
      'tags' => ['a'],
    ],
    '#markup' => 'parent',
    'child' => [
      '#cache' => [
        'contexts' => ['user.roles'],
        'tags' => ['b'],
      ],
      'grandchild' => [
        '#access_callback' => function () use (&$current_user_role) {
          // Only role A cannot access this subtree.
          return $current_user_role !== 'A';
        },
        '#cache' => [
          'contexts' => ['foo'],
          'tags' => ['c'],
          // A lower max-age; the redirecting cache item should be updated.
          'max-age' => 1800,
        ],
        'great grandchild' => [
          '#access_callback' => function () use (&$current_user_role) {
            // Only role C can access this subtree.
            return $current_user_role === 'C';
          },
          '#cache' => [
            'contexts' => ['bar'],
            'tags' => ['d'],
            // A lower max-age; the redirecting cache item should be updated.
            'max-age' => 300,
          ],
        ],
      ],
    ],
  ];

  // Request 1: role A, the grandchild isn't accessible => bubbled cache
  // contexts: user.roles.
  $element = $test_element;
  $current_user_role = 'A';
  $this->renderer->renderRoot($element);
  $this->assertRenderCacheItem(['parent'], [
    '#attached' => [],
    '#cache' => [
      'contexts' => ['user.roles'],
      'tags' => ['a', 'b'],
      'max-age' => Cache::PERMANENT,
    ],
    '#markup' => 'parent',
  ]);

  // Request 2: role B, the grandchild is accessible => bubbled cache
  // contexts: foo, user.roles + merged max-age: 1800.
  $element = $test_element;
  $current_user_role = 'B';
  $this->renderer->renderRoot($element);
  $this->assertRenderCacheItem(['parent'], [
    '#attached' => [],
    '#cache' => [
      'contexts' => ['user.roles', 'foo'],
      'tags' => ['a', 'b', 'c'],
      'max-age' => 1800,
    ],
    '#markup' => 'parent',
  ]);

  // Verify that request 1 is still cached and accessible.
  $current_user_role = 'A';
  $this->assertRenderCacheItem(['parent'], [
    '#attached' => [],
    '#cache' => [
      'contexts' => ['user.roles'],
      'tags' => ['a', 'b'],
      'max-age' => Cache::PERMANENT,
    ],
    '#markup' => 'parent',
  ]);

  // Request 3: role C, both the grandchild and the great grandchild are
  // accessible => bubbled cache contexts: foo, bar, user.roles + merged
  // max-age: 300.
  $element = $test_element;
  $current_user_role = 'C';
  $this->renderer->renderRoot($element);
  $this->assertRenderCacheItem(['parent'], [
    '#attached' => [],
    '#cache' => [
      'contexts' => ['user.roles', 'foo', 'bar'],
      'tags' => ['a', 'b', 'c', 'd'],
      'max-age' => 300,
    ],
    '#markup' => 'parent',
  ]);

  // Verify that request 2 and 3 are still cached and accessible.
  $current_user_role = 'A';
  $this->assertRenderCacheItem(['parent'], [
    '#attached' => [],
    '#cache' => [
      'contexts' => ['user.roles'],
      'tags' => ['a', 'b'],
      'max-age' => Cache::PERMANENT,
    ],
    '#markup' => 'parent',
  ]);

  $current_user_role = 'B';
  $this->assertRenderCacheItem(['parent'], [
    '#attached' => [],
    '#cache' => [
      'contexts' => ['user.roles', 'foo'],
      'tags' => ['a', 'b', 'c'],
      'max-age' => 1800,
    ],
    '#markup' => 'parent',
  ]);
}

/**
 * Tests bubbling of bubbleable metadata added by #pre_render callbacks.
 */
#[DataProvider('providerTestBubblingWithPrerender')]
public function testBubblingWithPrerender($test_element): void {
  $this->setUpRequest();
  $this->setUpMemoryCache();

  // Mock the State service.
  $time = $this->prophesize(TimeInterface::class)->reveal();
  $memory_state = new State(new KeyValueMemoryFactory(), new MemoryBackend($time), new NullLockBackend());
  \Drupal::getContainer()->set('state', $memory_state);

  // Simulate the theme system/Twig: a recursive call to Renderer::render(),
  // just like the theme system or a Twig template would have done.

   *
   * @param string $bulk_form_key
   *   The bulk form key representing the entity's id, language and revision (if
   *   applicable) as one string.
   *
   * @return \Drupal\Core\Entity\EntityInterface
   *   The entity loaded in the state (language, optionally revision) specified
   *   as part of the bulk form key.
   */
  protected function loadEntityFromBulkFormKey($bulk_form_key) {
    $key = base64_decode($bulk_form_key);
    $key_parts = json_decode($key);
    $revision_id = NULL;

    // If there are 3 items, vid will be last.
    if (count($key_parts) === 3) {
      $revision_id = array_pop($key_parts);
    }

    // The first two items will always be langcode and ID.
    $id = array_pop($key_parts);
    $langcode = array_pop($key_parts);

    // Load the entity or a specific revision depending on the given key.
    $storage = $this->entityTypeManager->getStorage($this->getEntityType());
    if ($revision_id) {
      /** @var \Drupal\Core\Entity\RevisionableStorageInterface $storage */
      $entity = $storage->loadRevision($revision_id);
    }
    else {
      $entity = $storage->load($id);
    }

    if ($entity instanceof TranslatableInterface) {
      $entity = $entity->getTranslation($langcode);
    }

    return $entity;
  }

  /**
   * {@inheritdoc}
   */
  public function isWorkspaceSafeForm(array $form, FormStateInterface $form_state): bool {
    $entity_type = $this->entityTypeManager->getDefinition($this->getEntityTypeId());
    return $this->isWorkspaceSafeEntityType($entity_type);
  }

}

